1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
5	
6	const messages = defineMessages({
7	  decrement: { id: 'zimm_quantity_stepper.decrement', defaultMessage: 'Decrease quantity' },
8	  increment: { id: 'zimm_quantity_stepper.increment', defaultMessage: 'Increase quantity' },
9	});
10	
11	/** Cart-line minimum meaningful quantity. 0 would mean "remove the line", a separate action this
12	 *  molecule does not own — see ZimmQuantityStepperProps.min. */
13	const MIN_DEFAULT = 1;
14	
15	export type ZimmQuantityStepperProps = {
16	  /** Current quantity rendered between the two buttons. */
17	  quantity: number;
18	  /** Lower bound (inclusive) — decrement disables at this value. Defaults to 1. */
19	  min?: number;
20	  /**
21	   * Upper bound (inclusive) — increment disables at this value. Always required: the caller
22	   * (inventory ATS, or a hardcoded per-SKU cap — see project memory on max order quantity) is the
23	   * one that knows the real ceiling. This molecule never computes or guesses one.
24	   */
25	  max: number;
26	  /**
27	   * Fully out-of-stock / unavailable for this line — forces BOTH buttons inert regardless of
28	   * where `quantity` sits between `min`/`max`, and dims the value display to match. This molecule
29	   * does not derive availability itself (no inventory lookups here) — the caller passes the
30	   * already-resolved flag.
31	   */
32	  isUnavailable?: boolean;
33	  /** Called with the computed next quantity (`quantity - 1`) when decrement is pressed while
34	   *  active. Never called while the decrement button is inert. */
35	  onDecrement: (nextQuantity: number) => void;
36	  /** Called with the computed next quantity (`quantity + 1`) when increment is pressed while
37	   *  active. Never called while the increment button is inert. */
38	  onIncrement: (nextQuantity: number) => void;
39	  /**
40	   * Id of an element (e.g. an active `ZimmInlineMessage`) describing this control's current
41	   * quantity/availability state — SFCC-795 plan step 3.6. Forwarded to BOTH buttons' own
42	   * `aria-describedby`, not just one: the message describes the stepper as a whole (e.g. "Maximum
43	   * purchase quantity reached for this size" is equally relevant whichever direction a shopper
44	   * reaches for), not one direction over the other. Undefined (every caller before this addition)
45	   * omits the attribute on both buttons entirely, unchanged from before this prop existed.
46	   */
47	  ariaDescribedBy?: string;
48	};
49	
50	/**
51	 * Molecule — cart-line quantity stepper (SFCC-271). Composes two `ZimmButton variant="icon"`
52	 * controls (hover/press/focus/disabled states are entirely zimmButton.css.ts's own, unchanged
53	 * here) around a numeric value display, styled by the co-located zimmQuantityStepper.css.ts.
54	 *
55	 * Controlled, not stateful: this component never mutates `quantity` itself, it only reports the
56	 * caller's next intended value via `onDecrement`/`onIncrement` — the actual basket update (an
57	 * SFCC SDK call) belongs to whichever container wires this in, per
58	 * .claude/rules/components.md's container/presentational separation. That wiring is a later
59	 * commit in this same build and has not happened yet.
60	 *
61	 * `ariaDisabled` (not `disabled`) is used for every inert state here, matching ZimmButton's own
62	 * documented guidance for an "unavailable but explainable" control: the button stays reachable
63	 * and announced by assistive tech (its dimmed appearance and the adjacent value are the
64	 * explanation) rather than disappearing from the tab order the way a native `disabled` attribute
65	 * would. `onClick` is additionally guarded inside this component (not just left to ZimmButton's
66	 * own ariaDisabled suppression) so the "clicking does nothing" contract holds even if that
67	 * changed.
68	 *
69	 * @param props see ZimmQuantityStepperProps
70	 */
71	export const ZimmQuantityStepper = ({
72	  quantity,
73	  min = MIN_DEFAULT,
74	  max,
75	  isUnavailable = false,
76	  onDecrement,
77	  onIncrement,
78	  ariaDescribedBy,
79	}: ZimmQuantityStepperProps) => {
80	  const intl = useIntl();
81	  const styles = useMultiStyleConfig('ZimmQuantityStepper', { disabled: isUnavailable });
82	
83	  const decrementInert = isUnavailable || quantity <= min;
84	  const incrementInert = isUnavailable || quantity >= max;
85	
86	  const handleDecrement = () => {
87	    if (decrementInert) return;
88	    onDecrement(quantity - 1);
89	  };
90	
91	  const handleIncrement = () => {
92	    if (incrementInert) return;
93	    onIncrement(quantity + 1);
94	  };
95	
96	  return (
97	    <chakra.div __css={styles.root}>
98	      <ZimmButton
99	        variant="icon"
100	        icon="minus"
101	        label={intl.formatMessage(messages.decrement)}
102	        ariaDisabled={decrementInert}
103	        ariaDescribedBy={ariaDescribedBy}
104	        onClick={handleDecrement}
105	      />
106	      {/* aria-live: a shopper-caused change to their own just-clicked control still benefits
107	          screen reader users exploring the surrounding value, not just the button they pressed. */}
