const path = require('path');
const webpack = require('webpack');

/** @type { import('@storybook/react-webpack5').StorybookConfig } */
const config = {
  stories: ['../overrides/**/*.stories.@(js|jsx|ts|tsx|mdx)'],
  // Serve overrides/app/static/ so self-hosted assets resolve in Storybook the same way
  // getAssetUrl resolves them in the app. Mapped to /static (rather than the bare directory)
  // so the fallback path in overrides/app/theme/fontFace.tsx is a real URL here instead of a
  // silent 404 — without this, Storybook renders the fallback font while the app renders
  // Futura Round, and no visual comparison made in Storybook can be trusted.
  staticDirs: [{ from: '../overrides/app/static', to: '/static' }],
  addons: [
    '@storybook/addon-webpack5-compiler-babel',
    '@storybook/addon-links',
    '@storybook/addon-docs',
    '@storybook/addon-a11y',
  ],
  framework: {
    name: '@storybook/react-webpack5',
    options: {},
  },
  webpackFinal: async (webpackConfig) => {
    // Resolve PWA Kit package aliases so imports from
    // '@salesforce/retail-react-app/...' resolve correctly.
    webpackConfig.resolve.alias = {
      ...webpackConfig.resolve.alias,
      // Project path aliases — keep in sync with babel.config.js, tsconfig.json
      // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
      '~': path.resolve(__dirname, '..'),
      app: path.resolve(__dirname, '../overrides/app'),
      '@salesforce/retail-react-app': path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      '@salesforce/pwa-kit-react-sdk': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-react-sdk'),
      '@salesforce/pwa-kit-runtime': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-runtime'),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, '../node_modules/@salesforce/commerce-sdk-react'),
      // @tanstack/react-query publishes separate CJS (build/lib/index.js) and ESM
      // (build/lib/index.mjs) entry points via its `exports` map. commerce-sdk-react's
      // dist `require()`s the CJS file while a raw `import` (used by a Storybook story
      // authored under overrides/) resolves the ESM file — two distinct files, so two
      // distinct copies of QueryClientProvider's module-scope Context objects. A
      // QueryClientProvider rendered from one copy is invisible to useQueryClient() called
      // from the other, throwing "No QueryClient set" despite a provider clearly being an
      // ancestor — confirmed via rightBar/index.stories.tsx's Wishlist icon
      // (withRegistration -> useCurrentCustomer). Force both `import` and `require` to the
      // same physical file so there is only ever one copy.
      '@tanstack/react-query': path.resolve(__dirname, '../node_modules/@tanstack/react-query/build/lib/index.js'),
    };

    // Allow Storybook to process JSX inside @salesforce/retail-react-app,
    // which ships un-compiled .jsx source files.
    webpackConfig.module.rules.push({
      test: /\.(js|jsx)$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      use: { loader: 'babel-loader' },
    });

    // @salesforce/pwa-kit-runtime/utils/ssr-config.js branches on this global (normally
    // injected by pwa-kit-dev's own webpack DefinePlugin for the 'web' target) to pick its
    // browser-safe ssr-config.client.js instead of the Node-only ssr-config.server.js, which
    // pulls in `cosmiconfig` (fs/os/module) and breaks the browser bundle. Storybook's webpack
    // config never set this, so the server-only branch was being bundled — see overrides/app
    // /config/contentful.ts, whose getConfig() import triggers it via the footer story.
    webpackConfig.plugins.push(
      new webpack.DefinePlugin({
        WEBPACK_TARGET: "'web'",
      }),
    );

    // Storybook adds a default asset/resource rule that catches all SVGs — remove it
    // so our scoped rules below can take full control.
    webpackConfig.module.rules = webpackConfig.module.rules.filter(
      (rule) => !(rule?.test instanceof RegExp && rule.test.test('.svg')),
    );

    // Mirror the PWA Kit browser build: SFCC SVGs are sprite-loaded server-side only,
    // so the browser (and Storybook) should ignore those imports entirely.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      loader: 'ignore-loader',
    });

    // Treat project SVGs as file assets.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      exclude: /node_modules/,
      type: 'asset/resource',
    });

    return webpackConfig;
  },
};

module.exports = config;

// Global a11y-check exclusion list (see preview.tsx). A story-level
// `parameters.a11y.context.exclude` REPLACES this array rather than extending it (Storybook's
// parameters merge is shallow) — a story under overrides/ that needs its own additional
// exclusion duplicates these same six IDs locally rather than importing across the
// .storybook/<->overrides/ boundary (a 4+ level relative import; see
// list-menu/list-menu.stories.content.ts for the one current example, which cross-references
// this file in a comment instead).
export const CHAKRA_TOAST_A11Y_EXCLUDE = [
  // Chakra UI injects toast region containers (role="region") at the root without an
  // accessible name — a known upstream limitation, framework-level not component output.
  '#chakra-toast-manager-top',
  '#chakra-toast-manager-top-right',
  '#chakra-toast-manager-top-left',
  '#chakra-toast-manager-bottom',
  '#chakra-toast-manager-bottom-right',
  '#chakra-toast-manager-bottom-left',
];

import React from 'react';
import type { Preview, Decorator } from '@storybook/react-webpack5';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from '../overrides/app/theme';
import { ZimmTokensGlobal } from '../overrides/app/theme/zimmTokensGlobal';
import { ZimmFontFace } from '../overrides/app/theme/fontFace';
import { CHAKRA_TOAST_A11Y_EXCLUDE } from './a11yExcludes';

// @salesforce/pwa-kit-runtime's browser-side getConfig() (utils/ssr-config.client.js) just
// reads window.__CONFIG__, which the real app's SSR bootstrap script sets and Storybook never
// does — every call site that reads getConfig().app (Zimmermann's own, e.g.
// overrides/app/config/contentful.ts, and base SFCC vendor code, e.g. use-auth-modal.js's and
// otp-auth/index.jsx's getConfig().app.login) throws in Storybook without this. `login: {}` is
// needed alongside `app: {}` — every other getConfig().app.* read in base SFCC guards with `?.`
// or `|| {}`, but otp-auth/index.jsx's `const {tokenLength} = getConfig().app.login` does not,
// so `.login` itself must already be an object. `sites` is needed for any story whose play
// function clicks a button that calls useNavigation() → removeSiteLocaleFromPath() →
// getConfigMatcher() → getSites(), which throws when sites is empty. Not a copy of real config
// values — just enough shape for vendor code's unguarded reads.
if (typeof window !== 'undefined') {
  (window as typeof window & { __CONFIG__?: { app: Record<string, unknown> } }).__CONFIG__ = {
    app: {
      login: {},
      sites: [
        {
          id: 'ZimmermannAU',
          alias: 'au',
          l10n: {supportedLocales: [{id: 'en-AU', alias: 'en-AU'}]},
        },
      ],
    },
  };
}

// ZimmTokensGlobal injects the --zimm-* :root custom properties, mirroring what
// _app-config does in the app. Without it, the .zimm-* global classes and the
// var(--zimm-*) component overrides (button/header/listMenu) render unresolved in
// Storybook. Same shared source as the app, so the two cannot drift.
//
// ZimmFontFace declares the self-hosted Futura Round faces, likewise mirroring
// _app-config. Without it Storybook renders the fallback stack while the app renders
// Futura Round — the fallback measures ~13% wider, so any visual comparison made in
// Storybook would not match the app or Figma. Font files are served here by the
// staticDirs mapping in .storybook/main.js.
const withChakra: Decorator = (Story) => (
  <ChakraProvider theme={theme}>
    <ZimmFontFace />
    <ZimmTokensGlobal />
    <Story />
  </ChakraProvider>
);

const withIntl: Decorator = (Story) => (
  <IntlProvider locale="en-AU" defaultLocale="en-AU">
    <Story />
  </IntlProvider>
);

const preview: Preview = {
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /date$/i,
      },
    },
    layout: 'centered',
    a11y: {
      // 'error' causes a11y violations to fail test-storybook --ci runs
      test: 'error',
      // See a11yExcludes.ts — Storybook's parameters merge is shallow, so a story that sets
      // its own parameters.a11y.context.exclude REPLACES this array rather than extending it;
      // that file's own comment documents how a story adds to it instead.
      context: {
        exclude: CHAKRA_TOAST_A11Y_EXCLUDE,
      },
    },
  },
  decorators: [withChakra, withIntl],
};

export default preview;
